changeSet.sql:
create or alter procedure [graph].[Hop_GetSelf] @diagramType int, @hopSalt varchar(25), @leafOnly bit as begin set nocount on;
insert into #links (Direction, HopNumber, [Key], ID, AssetUid, [Path], [Segment], IsFocal) select '-', 0 as HopNumber, A.[Key],
N.ID as ToID, N.Uid as ToUid, N.[Path] as ToPath, N.Segments as ToSegment, 1 as IsFocal from graph.AssetNode N, #assetIds A where N.ID = A.ID;
if @diagramType = 2 begin insert into #nodes ([Level], AssetUid, AssetID, [Key], Back, Fore, Icon, AssetTypeID, AssetTypeUid, Class, DisplayValue, Reveal, ActionCount, RelationCounts, UseAsTransformation, IsLeaf, Parsed, IsFocal) select distinct 2 ,A.Uid as AssetUid ,A.ID as AssetID ,L.[Key] ,A.BackColor as Back ,A.ForeColor as Fore ,A.Icon ,A.AssetTypeID ,A.AssetTypeUid ,A.AssetTypeClass as Class ,V.DisplayValue ,0 as Reveal ,0 as ActionCount ,'[]' as RelationCounts ,0 as UseAsTransformation ,1 as IsLeaf ,0 as Parsed ,L.IsFocal from #links L inner join AssetWithType A on A.ID = L.ID left join AssetDisplayValue V on V.AssetID = L.ID; end else begin exec graph.Hop_LoadHopHierarchies @hopSalt, '-', 0;
with d as ( select p.[Level] + 1 as [Level], T.Uid as AssetUid, T.ID as AssetID, cast(utility.GetHash(@hopSalt + '|' + cast(T.ID as varchar)) as varchar(50)) [Key], p.AssetID as ParentID, p.[Key] as ParentKey, cast(1 as bit) as IsFocal from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #nodes p, #assetIds A where MATCH(S-(E)->T) and E.PredicateType in (3, 4) and S.ID = p.AssetID and A.ID = p.AssetID union all select p.[Level] + 1 as [Level], T.Uid as AssetUid, T.ID as AssetID, cast(utility.GetHash(@hopSalt + '|' + cast(T.ID as varchar)) as varchar(50)) [Key], p.AssetID as ParentID, p.[Key] as ParentKey, cast(0 as bit) as IsFocal from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, d p where MATCH(S-(E)->T) and E.PredicateType in (3, 4) and S.ID = p.AssetID )
insert into #nodes ([Level], AssetUid, AssetID, [Key], ParentID, ParentKey, Back, Fore, Icon, AssetTypeID, AssetTypeUid, Class, DisplayValue, Reveal, ActionCount, RelationCounts, UseAsTransformation, IsLeaf, Parsed, IsFocal) select distinct d.[Level] ,d.AssetUid ,d.AssetID ,d.[Key] ,d.ParentID ,d.[ParentKey] ,A.BackColor as Back ,A.ForeColor as Fore ,A.Icon ,A.AssetTypeID ,A.AssetTypeUid ,A.AssetTypeClass as Class ,coalesce(V.DisplayValue, '{Unknown}') as DisplayValue ,0 as Reveal ,0 as ActionCount ,'[]' as RelationCounts ,0 as UseAsTransformation ,cast(0 as bit) as IsLeaf ,0 ,d.IsFocal from d inner join AssetWithType A on A.ID = d.AssetID left join AssetDisplayValue V on V.AssetID = d.AssetID;
declare @maxLevel int = 1 select @maxLevel = max([Level]) from #nodes update #nodes set isLeaf = case [level] when @maxLevel then 1 else 0 end; end;
exec graph.Hop_LoadSingleParentHeirarchies @hopSalt, '-', 0;
-- This indicates which assets will be used for subsequent hops, as well as which direction. exec graph.Hop_LoadNextHopAssets 'B', 0, 0, @leafOnly exec graph.Hop_LoadNextHopAssets 'F', 0, 0, @leafOnly end
